using System;using System.Collections.Generic;using System.IO;using System.IO.Compression;using System.Linq;using System.Net;using System.Net.Sockets;using System.Text;using System.Threading;using System.Web.Script.Serialization;using System.Xml;using System.Xml.Linq;using System.Xml.Schema;using SlopProX;
internal static class StudioIntegrationTests
{
 static List<string> lines=new List<string>();static int failed;static string folder,app;static void Assert(bool value,string error){if(!value)throw new Exception(error);}static void Test(string name,Action action){try{action();lines.Add("PASS "+name);}catch(Exception ex){failed++;lines.Add("FAIL "+name+" :: "+ex);}}
 static string Wav(string name,float value,bool impulse){string file=Path.Combine(folder,name+".wav");using(var w=new ExportWaveWriter(file,48000,1,24,false)){float[] data=new float[48000];if(impulse)data[0]=value;else for(int i=0;i<data.Length;i++)data[i]=value;w.Write(data,0,data.Length);}return file;}
 static ProjectDocument AudioProject(string file){var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("Audio",TrackType.Audio);t.Regions.Add(new Region{MediaPath=file,StartBeat=0,LengthBeats=2});p.Tracks.Add(t);return p;}
 static object Rpc(string method,int id,object args){return new Dictionary<string,object>{{"jsonrpc","2.0"},{"id",id},{"method",method},{"params",args}};}
 static byte[] Note(int position,int length,int channel,int key,int velocity){byte[] b=new byte[24];Array.Copy(BitConverter.GetBytes(position),0,b,0,4);Array.Copy(BitConverter.GetBytes((ushort)channel),0,b,6,2);Array.Copy(BitConverter.GetBytes(length),0,b,8,4);Array.Copy(BitConverter.GetBytes((ushort)key),0,b,12,2);b[21]=(byte)velocity;return b;}
 static void Event(BinaryWriter w,int id,byte[] data){w.Write((byte)id);if(id>=192){int n=data.Length;while(n>=128){w.Write((byte)((n&127)|128));n>>=7;}w.Write((byte)n);}w.Write(data);}
 [STAThread]static int Main(string[] args){folder=Path.Combine(args[0],DateTime.UtcNow.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8));app=AppDomain.CurrentDomain.BaseDirectory;Directory.CreateDirectory(folder);
 Test("studio state .slopdaw round-trip, undo/redo and validation",delegate{var p=AudioProject(Wav("model",.1f,false));var t=p.Tracks[0];p.Studio.Inputs.Add(new InputRoute{TrackId=t.Id,Channel=1,Channels=1,Monitor=true});p.Studio.Cells.Add(new LauncherCell{TrackId=t.Id,RegionId=t.Regions[0].Id,Scene=2});p.Studio.Automation.Add(new AutomationLane{TrackId=t.Id,Target="Volume",Points=new List<AutomationPoint>{new AutomationPoint{Beat=0,Value=-6},new AutomationPoint{Beat=4,Value=0}}});var reopened=ProjectFile.Deserialize(ProjectFile.Serialize(p));Assert(ProjectFile.Equivalent(p,reopened),"Studio content lost.");var before=p.Studio.Copy();var after=before.Copy();after.Cells.Clear();var history=new ProjectHistory();history.Execute(p,new SetStudioCommand("Cell",before,after));history.Undo(p);Assert(p.Studio.Cells.Count==1,"Undo failed.");history.Redo(p);Assert(p.Studio.Cells.Count==0,"Redo failed.");var blank=ProjectFile.Deserialize(ProjectFile.Serialize(new ProjectDocument()));Assert(blank.Studio!=null,"Studio defaults failed.");bool rejected=false;after.Inputs[0].Channel=32;try{after.Validate(p);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Invalid routing accepted.");});
 Test("two actual PCM recording files from independent synthetic input channels",delegate{var left=ProjectFactory.CreateTrack("Left",TrackType.Audio);var right=ProjectFactory.CreateTrack("Right",TrackType.Audio);var studio=new StudioState();studio.Inputs.Add(new InputRoute{TrackId=right.Id,Channel=1});using(var record=new AudioRecordingSession(new[]{left,right},studio,Path.Combine(folder,"takes"),48000,2)){float[] input=new float[9600];for(int i=0;i<4800;i++){input[i*2]=.1f;input[i*2+1]=-.2f;}record.Receive(input,4800,2,0);var takes=record.Finish();Assert(takes.Count==2,"Expected two takes.");foreach(var take in takes){var wave=WaveAudio.Load(take.Path);Assert(wave.Info.Channels==1&&Math.Abs(wave.Info.DurationSeconds-.1)<.00001,"Invalid recorded format.");short value=BitConverter.ToInt16(wave.Samples,0);Assert(take.TrackId==left.Id?value>3000&&value<3400:value<-6400&&value>-6800,"Input channels crossed.");}}});
 Test("real input monitoring through track gain/pan and output mix",delegate{var p=new ProjectDocument();var t=ProjectFactory.CreateTrack("Monitor",TrackType.Audio);p.Tracks.Add(t);p.Studio.Inputs.Add(new InputRoute{TrackId=t.Id,Channels=2,Monitor=true});using(var e=new ArrangementEngine(new AppSettings())){e.SetProject(p);float[] input=new float[1024];for(int i=0;i<512;i++){input[i*2]=.1f;input[i*2+1]=.2f;}e.InjectAudioInput(input,512,2);float[] output=new float[1024];e.Render(output,512,0);Assert(Math.Abs(output[100]-.1)<.00001&&Math.Abs(output[101]-.2)<.00001,"Monitor path failed.");}});
 Test("sample-wise volume automation affects rendered PCM",delegate{var p=AudioProject(Wav("automation",.2f,false));p.Studio.Automation.Add(new AutomationLane{TrackId=p.Tracks[0].Id,Points=new List<AutomationPoint>{new AutomationPoint{Beat=0,Value=0},new AutomationPoint{Beat=1,Value=-6}}});using(var e=new ArrangementEngine(new AppSettings())){var data=e.RenderOffline(p,25000,0);Assert(data[0]>.199&&data[48000]>.099&&data[48000]<.102,"Automation not applied at the musical time.");Assert(data[2000]>data[2002],"Automation is not evaluated per sample.");}});
 Test("VST3 / CLAP sample-offset parameter automation through worker IPC",delegate{foreach(string extension in new[]{"vst3","clap"})using(var plugin=new NativePlugin(NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureGain."+extension))[0].CreateSlot(),48000,512)){plugin.QueueParameter(1000,.25,0);plugin.QueueParameter(1000,.75,128);var data=Enumerable.Repeat(.2f,1024).ToArray();plugin.Process(data,512,new MidiEventPacket[0],0,120,0,true,4,4);Assert(Math.Abs(data[0]-.1)<.00001&&Math.Abs(data[254]-.1)<.00001&&Math.Abs(data[256]-.3)<.00001,"Parameter event offset lost: "+extension);}});
 Test("four automated plugin parameters remain bounded on a short 61-frame segment",delegate{var p=AudioProject(Wav("short-segment",.2f,false));var slot=NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureGain.clap"))[0].CreateSlot();p.Tracks[0].Plugins.Add(slot);for(uint id=1000;id<1004;id++)p.Studio.Automation.Add(new AutomationLane{TrackId=p.Tracks[0].Id,Target="Plugin:"+slot.Id.ToString()+":"+id,Points=new List<AutomationPoint>{new AutomationPoint{Beat=0,Value=.5}}});using(var e=new ArrangementEngine(new AppSettings())){var data=e.RenderOffline(p,61,0);Assert(data.Max()>.19,"Short segment overflowed the parameter event queue.");}});
 Test("per-instance CLAP DSP exit, hang and native access-violation isolation preserves another real plugin",delegate{var descriptor=NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureSandbox.clap"))[0];var safe=NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureGain.clap"))[0];using(var other=new NativePlugin(safe.CreateSlot(),48000,512)){foreach(double fault in new[]{.75,.875,.975}){using(var bad=new NativePlugin(descriptor.CreateSlot(),48000,512)){float[] buffer=Enumerable.Repeat(.2f,1024).ToArray();bad.Process(buffer,512,new MidiEventPacket[0],0,120,0,true,4,4);bad.SetParameter(1000,fault);bool caught=false;var watch=System.Diagnostics.Stopwatch.StartNew();try{bad.Process(buffer,512,new MidiEventPacket[0],0,120,0,true,4,4);}catch{caught=true;}Assert(caught&&!bad.Healthy,"Fault was not isolated.");Assert(watch.ElapsedMilliseconds<1500,"Failure deadline unbounded.");lines.Add("DSP fault="+fault+" parent survived; detection="+watch.ElapsedMilliseconds+" ms");}float[] data=Enumerable.Repeat(.25f,1024).ToArray();other.Process(data,512,new MidiEventPacket[0],0,120,0,true,4,4);Assert(Math.Abs(data[0]-.25)<.00001,"Other plugin affected by crash.");}}});
 Test("reported 256-sample plugin latency compensates dry track impulse",delegate{var p=AudioProject(Wav("pdc",.25f,true));var two=ProjectFactory.CreateTrack("Delayed",TrackType.Audio);two.Regions.Add(new Region{MediaPath=p.Tracks[0].Regions[0].MediaPath,LengthBeats=2});two.Plugins.Add(NativePlugin.Scan(Path.Combine(app,"TestFixtures","FixtureSandbox.clap"))[0].CreateSlot());p.Tracks.Add(two);using(var e=new ArrangementEngine(new AppSettings())){var audio=e.RenderOffline(p,1024,0);Assert(e.CompensationSamples==256,"Latency not reported.");Assert(Math.Abs(audio[0])<.000001&&audio[512]>.499&&audio[512]<.501,"PDC impulses did not align.");}});
 Test("Slop Launcher quantized launch, repeated audio cell and stop/arrangement return",delegate{var p=AudioProject(Wav("launcher",.15f,false));using(var e=new ArrangementEngine(new AppSettings())){e.PrepareOffline(p,0);float[] block=new float[1024];e.Render(block,512,0);e.Launch(p.Tracks[0].Id,p.Tracks[0].Regions[0].Id,1);Assert(!e.IsLaunched(p.Tracks[0].Id,p.Tracks[0].Regions[0].Id),"Launch ignored quantization.");for(int i=0;i<49;i++)e.Render(block,512,0);Assert(e.IsLaunched(p.Tracks[0].Id,p.Tracks[0].Regions[0].Id),"Queued launch missing.");for(int i=0;i<160;i++)e.Render(block,512,0);Assert(block.Max()>.149,"Audio cell did not loop.");e.Launch(p.Tracks[0].Id,null,0);e.Render(block,512,0);Assert(block.All(v=>Math.Abs(v)<.000001),"Stop-cell did not silence track.");e.ReturnToArrangement();}});
 Test("comp segments route actual selected take audio and persist",delegate{var p=AudioProject(Wav("comp-a",.1f,false));var t=p.Tracks[0];var b=new Region{MediaPath=Wav("comp-b",.2f,false),StartBeat=0,LengthBeats=2};t.Regions.Add(b);p.Studio.Comps.Add(new CompLane{TrackId=t.Id,Takes=t.Regions.Select(r=>r.Id).ToList(),Slices=new List<CompSlice>{new CompSlice{RegionId=t.Regions[0].Id,StartBeat=0,EndBeat=1},new CompSlice{RegionId=b.Id,StartBeat=1,EndBeat=2}}});p=ProjectFile.Deserialize(ProjectFile.Serialize(p));using(var e=new ArrangementEngine(new AppSettings())){var audio=e.RenderOffline(p,48000,0);Assert(Math.Abs(audio[100]-.1)<.00001&&Math.Abs(audio[50000]-.2)<.00001,"Comp mix wrong.");}});
 Test("offline stereo bounce writes valid 16/24-bit PCM and IEEE float with correct duration",delegate{var p=AudioProject(Wav("export-source",.1f,false));foreach(int bits in new[]{16,24,32}){string file=Path.Combine(folder,"bounce-"+bits+".wav");AudioExport.Render(p,file,new AudioExportOptions{SampleRate=44100,Bits=bits,Float=bits==32,EndBeat=2},CancellationToken.None,null);var data=WaveAudio.Load(file);Assert(data.Info.Channels==2&&data.Info.SampleRate==44100&&Math.Abs(data.Info.DurationSeconds-1)<.00001&&data.Info.BitsPerSample==bits,"Bounce format/duration mismatch.");}});
 Test("bounce tail renders effect decay without later arrangement regions",delegate{var p=AudioProject(Wav("tail-source",.2f,false));p.Tracks[0].Regions.Add(new Region{MediaPath=p.Tracks[0].Regions[0].MediaPath,StartBeat=2.5,LengthBeats=2});string file=Path.Combine(folder,"tail.wav");AudioExport.Render(p,file,new AudioExportOptions{SampleRate=48000,Bits=24,EndBeat=2,TailSeconds=.5},CancellationToken.None,null);var audio=WaveAudio.Load(file);Assert(Math.Abs(audio.Info.DurationSeconds-1.5)<.00001,"Tail duration incorrect.");for(int i=48000*2*3;i<audio.Samples.Length;i++)Assert(audio.Samples[i]==0,"A region after the export endpoint leaked into the tail.");});
 Test("Slop Pitch detects A4 and renders C5 without changing duration",delegate{string file=Path.Combine(folder,"pitch-source.wav");float[] data=new float[48000];for(int i=0;i<data.Length;i++)data[i]=(float)(.3*Math.Sin(2*Math.PI*440*i/48000));using(var w=new ExportWaveWriter(file,48000,1,24,false))w.Write(data,0,data.Length);var analysis=PitchAnalysis.Analyze(file,0,1);Assert(analysis.Segments.Count>0&&Math.Abs(analysis.Segments[0].Midi-69)<.15,"Pitch detection failed.");foreach(var segment in analysis.Segments)segment.Target=72;string output=Path.Combine(folder,"pitch-c5.wav");analysis.Save(output);Assert(Math.Abs(WaveAudio.Inspect(output).DurationSeconds-1)<.00001,"Pitch edit changed duration.");var shifted=PitchAnalysis.Analyze(output,.15,.65);double midi=shifted.Segments.Select(s=>s.Midi).DefaultIfEmpty(0).Average();Assert(Math.Abs(midi-72)<.45,"Rendered pitch wrong: "+midi);lines.Add("PITCH detected="+analysis.Segments[0].Midi+" rendered="+midi);});
 Test("DAWproject standard XML XSD validation, embedded audio and native round-trip",delegate{var p=AudioProject(Wav("exchange",.1f,false));var midi=ProjectFactory.CreateTrack("Notes",TrackType.Midi);var region=new Region{LengthBeats=4};region.Notes.Add(new MidiNote{Pitch=64,LengthBeats=1});midi.Regions.Add(region);p.Tracks.Add(midi);string file=Path.Combine(folder,"roundtrip.dawproject");ProjectExchange.ExportDawProject(p,file);using(var zip=ZipFile.OpenRead(file)){XDocument xml;using(var stream=zip.GetEntry("project.xml").Open())xml=XDocument.Load(stream);var schemas=new XmlSchemaSet();schemas.Add("",args[1]);xml.Validate(schemas,delegate(object sender,ValidationEventArgs error){throw error.Exception;});Assert(xml.Descendants("Note").Count()==1&&xml.Descendants("Audio").Count()==1,"Standard interchange content missing.");}var reopened=ProjectExchange.ImportDawProject(file,Path.Combine(folder,"extracted"));Assert(reopened.Project.Tracks.Count==2&&File.Exists(reopened.Project.Tracks[0].Regions[0].MediaPath)&&reopened.Project.Tracks[1].Regions[0].Notes[0].Pitch==64,"DAWproject content lost.");});
 Test("external DAWproject notes and missing-plugin handling without native extension",delegate{string file=Path.Combine(folder,"external.dawproject");using(var zip=ZipFile.Open(file,ZipArchiveMode.Create)){using(var w=new StreamWriter(zip.CreateEntry("project.xml").Open()))w.Write("<Project version='1.0'><Application name='Fixture' version='1'/><Transport><Tempo value='125'/></Transport><Structure><Track id='t' name='Piano' contentType='notes'><Channel role='regular'><Devices><ClapPlugin deviceID='missing' deviceName='Unavailable' deviceRole='instrument'/></Devices></Channel></Track></Structure><Arrangement><Lanes timeUnit='beats'><Lanes track='t'><Clips><Clip time='4' duration='4'><Notes><Note time='0' duration='1' channel='0' key='67' vel='0.7'/></Notes></Clip></Clips></Lanes></Lanes></Arrangement></Project>");}var imported=ProjectExchange.ImportDawProject(file,Path.Combine(folder,"external-media"));Assert(imported.Project.Tempo==125&&imported.Project.Tracks[0].Regions[0].Notes[0].Pitch==67&&imported.Project.Tracks[0].Plugins[0].Path==""&&imported.Warnings.Count>0,"External import wrong.");});
 Test("ALS gzip XML arrangement note import with unsupported-device disclosure",delegate{string file=Path.Combine(folder,"fixture.als");using(var f=File.Create(file))using(var gz=new GZipStream(f,CompressionMode.Compress))using(var w=new StreamWriter(gz))w.Write("<Ableton><LiveSet><MasterTrack><Tempo><Manual Value='128'/></Tempo></MasterTrack><Tracks><MidiTrack><Name><EffectiveName Value='Lead'/></Name><DeviceChain><MidiClip><CurrentStart Value='2'/><CurrentEnd Value='6'/><Loop><LoopStart Value='0'/></Loop><Name Value='Phrase'/><Notes><KeyTrack><MidiKey Value='62'/><Notes><MidiNoteEvent Time='0.5' Duration='0.25' Velocity='101'/></Notes></KeyTrack></Notes></MidiClip></DeviceChain></MidiTrack></Tracks></LiveSet></Ableton>");var imported=ProjectExchange.ImportAls(file);Assert(imported.Project.Tempo==128&&imported.Project.Tracks[0].Regions[0].StartBeat==2&&imported.Project.Tracks[0].Regions[0].Notes[0].Pitch==62&&imported.Warnings.Count>0,"ALS notes/timing wrong.");});
 Test("FLP binary note and playlist import with bounded event parser",delegate{string file=Path.Combine(folder,"fixture.flp");using(var events=new MemoryStream())using(var w=new BinaryWriter(events)){Event(w,65,BitConverter.GetBytes((ushort)1));Event(w,193,Encoding.Unicode.GetBytes("Pattern\0"));Event(w,224,Note(48,96,0,60,80));byte[] playlist=new byte[32];Array.Copy(BitConverter.GetBytes(384),playlist,4);Array.Copy(BitConverter.GetBytes((ushort)20480),0,playlist,4,2);Array.Copy(BitConverter.GetBytes((ushort)20481),0,playlist,6,2);Array.Copy(BitConverter.GetBytes(384),0,playlist,8,4);Event(w,233,playlist);using(var output=new BinaryWriter(File.Create(file))){output.Write(Encoding.ASCII.GetBytes("FLhd"));output.Write(6);output.Write((short)0);output.Write((ushort)1);output.Write((ushort)96);output.Write(Encoding.ASCII.GetBytes("FLdt"));output.Write((int)events.Length);output.Write(events.ToArray());}}var imported=ProjectExchange.ImportFlp(file);var region=imported.Project.Tracks[0].Regions[0];Assert(region.StartBeat==4&&region.Notes[0].StartBeat==.5&&region.Notes[0].Pitch==60&&imported.Warnings.Count>0,"FLP notes/playlist timing wrong.");});
 Test("OSC typed messages and bidirectional localhost UDP integration",delegate{var message=OscCodec.Decode(OscCodec.Encode("/avatar/parameters/Test",true,.5f,42,"hello"))[0];Assert((bool)message.Arguments[0]&&Math.Abs(Convert.ToSingle(message.Arguments[1])-.5)<.00001&&(int)message.Arguments[2]==42,"OSC codec failed.");var a=new IntegrationSettings{OscReceivePort=49431,OscSendPort=49432};var b=new IntegrationSettings{OscReceivePort=49432,OscSendPort=49431};using(var one=new OscConnection(a))using(var two=new OscConnection(b))using(var signal=new AutoResetEvent(false)){two.Message+=delegate(OscMessage m){if(m.Address=="/slop/play")signal.Set();};one.Send("/slop/play",true);Assert(signal.WaitOne(1000),"OSC UDP not received.");}});
 Test("MCP lifecycle/tool registry/shared-command dispatch via real stdio streams",delegate{int calls=0;var server=new McpServer(delegate(string name,IDictionary<string,object> values){calls++;return new {tempo=values["bpm"]};});var json=new JavaScriptSerializer();string input=json.Serialize(Rpc("initialize",1,new {protocolVersion="2025-11-25"}))+"\n"+json.Serialize(new {jsonrpc="2.0",method="notifications/initialized"})+"\n"+json.Serialize(Rpc("tools/list",2,new {}))+"\n"+json.Serialize(Rpc("tools/call",3,new {name="set_tempo",arguments=new {bpm=132}}))+"\n";using(var source=new MemoryStream(Encoding.UTF8.GetBytes(input)))using(var dest=new MemoryStream()){server.Run(source,dest);string output=Encoding.UTF8.GetString(dest.ToArray());Assert(calls==1&&output.Contains("create_track")&&output.Contains("132")&&output.Split('\n').Count(s=>s.Length>0)==3,"MCP stdio failed.");}});
 Test("recovery snapshot preserves supported content and detects an unclean prior session",delegate{string root=Path.Combine(folder,"recovery-profile");var store=new RecoveryStore(root);var p=new ProjectDocument{Name="Recovery fixture"};store.Snapshot(p,null);string session=Directory.GetDirectories(Path.Combine(root,"Recovery"))[0];string metadata=Path.Combine(session,"session.json");var json=new JavaScriptSerializer();var record=json.Deserialize<Dictionary<string,object>>(File.ReadAllText(metadata));record["Pid"]=0;File.WriteAllText(metadata,json.Serialize(record));var found=RecoveryStore.Find(root);Assert(found.Count==1&&ProjectFile.Load(found[0].Snapshot).Name=="Recovery fixture","Recovery missing.");store.Close();Assert(RecoveryStore.Find(root).Count==0,"Clean session offered as crash recovery.");});
 File.WriteAllLines(Path.Combine(folder,"studio-tests.txt"),lines);foreach(var line in lines)Console.WriteLine(line);Console.WriteLine("RESULT "+(lines.Count(l=>l.StartsWith("PASS")))+" passed, "+failed+" failed");return failed==0?0:1;}
}
